import{_ as a,c as e,o as d,b0 as o}from"./chunks/framework.C5ev1SXp.js";const s="/scm-docs/assets/storage-and-slots.DTjYiaLq.svg",n="/scm-docs/assets/upgrade-stages.CZj2Kyge.svg",p="/scm-docs/assets/record-frame.DyPxIMN_.svg",l="/scm-docs/assets/go-flash-flow.Bn-WE8WF.svg",r="/scm-docs/assets/slot-state.DHi8ursI.svg",x=JSON.parse('{"title":"LV075-app在线升级原理与流程设计","description":null,"frontmatter":{"title":"LV075-app在线升级原理与流程设计","date":"2026-10-31T16:10:25.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/esp8266/126d6390acc10a333286fe9a","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-31T16:10:25.163Z","fulluuid":"33286fe9a1074d00b862bd455b972517","useduuid":"33286fe9a"}},"headers":[],"relativePath":"sdoc/advanced-chapter/esp8266/126d6390acc10a333286fe9a.md","filePath":"sdoc/70-在线升级/01-IAP/LV075-app在线升级原理与流程设计.md","lastUpdated":1794036996000}'),i={name:"sdoc/advanced-chapter/esp8266/126d6390acc10a333286fe9a.md"};function c(h,t,u,b,g,m){return d(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="lv075-app在线升级原理与流程设计" tabindex="-1">LV075-app在线升级原理与流程设计 <a class="header-anchor" href="#lv075-app在线升级原理与流程设计" aria-label="Permalink to &quot;LV075-app在线升级原理与流程设计&quot;">​</a></h1><blockquote><p><strong>前置阅读</strong>：<a href="/scm-docs/sdoc/advanced-chapter/esp8266/126d638f36e925e464c8cbd0.html">LV045-WiFi-TFTP文件下载</a>（在《ESP8266》章节）解决了&quot;怎么把 <code>app.img</code> 从局域网拉进外部 SRAM&quot;，本篇接着讲&quot;拉进来之后怎么安全地装进内部 Flash&quot;。链路上两道校验各自成篇：CRC32 的原理见 <a href="./LV080-CRC32校验原理.html">LV080-CRC32校验原理</a>，镜像签名与验签见 <a href="./LV085-Ed25519签名校验原理.html">LV085-Ed25519签名校验原理</a>——本篇只讲它们在流程里的位置和分工。</p></blockquote><p>在线升级最容易被写成一个&quot;能跑就行&quot;的流程：下载、擦、写、跳转，四步走完，测试时一切正常。但只要把这四步放到真实环境里，问题立刻出现——<strong>正在执行的那份代码，正好就是准备被擦掉的那份</strong>。擦到一半掉电，设备就既跑不了新程序，也回不到旧程序。</p><p>所以这一整套设计其实在回答一个问题：<em>如何让&quot;替换自己&quot;这件事在任何时刻被打断，都还留有一条完整的退路。</em></p><p>答案被拆成了三方：<strong>app 只负责把新镜像放进交接区，bootloader 只负责把交接区的东西装进内部 Flash，中间用一份掉电不丢的记录串起来</strong>。本篇就按这个顺序，把每一处设计的理由讲清楚。</p><h2 id="一、-升级要跨两个执行环境" tabindex="-1">一、 升级要跨两个执行环境 <a class="header-anchor" href="#一、-升级要跨两个执行环境" aria-label="Permalink to &quot;一、 升级要跨两个执行环境&quot;">​</a></h2><h3 id="_1-谁在什么位置运行" tabindex="-1">1. 谁在什么位置运行 <a class="header-anchor" href="#_1-谁在什么位置运行" aria-label="Permalink to &quot;1. 谁在什么位置运行&quot;">​</a></h3><p>板子上有两段互不重叠的代码，分别由两次独立编译产出：</p><table tabindex="0"><thead><tr><th>程序</th><th>链接地址</th><th>职责</th><th>谁更新它</th></tr></thead><tbody><tr><td>bootloader</td><td><code>0x08000000</code></td><td>上电第一段、收固件、跳转、装 A/B 槽</td><td>J-Link（唯一允许的通道）</td></tr><tr><td>flash app</td><td><code>0x08020000</code></td><td>业务功能、WiFi 下载、写槽、确认</td><td>只能靠 bootloader 搬运</td></tr></tbody></table><p>关键点在于第二行的&quot;只能靠 bootloader 搬运&quot;。app 自己不能覆盖 <code>0x08020000</code>。</p><h3 id="_2-为什么-app-不能自己擦内部-flash" tabindex="-1">2. 为什么 app 不能自己擦内部 Flash <a class="header-anchor" href="#_2-为什么-app-不能自己擦内部-flash" aria-label="Permalink to &quot;2. 为什么 app 不能自己擦内部 Flash&quot;">​</a></h3><p>这不是保守，是硬性限制：</p><ol><li><strong>自擦除会取指失败</strong>。app 的代码就跑在 <code>0x08020000</code> 起始的区域里。擦除操作以 1KB/2KB 页为单位，一旦擦到当前 PC 所在的页，下一条指令就再也取不到了——不是报错，是直接 HardFault 或跑飞。</li><li><strong>擦写期间没有可用中断</strong>。内部 Flash 编程时总线会阻塞，任何跑到 Flash 里取指的中断服务程序都会卡住。业务代码里定时器、串口、WiFi 全在跑，关不完。</li><li><strong>没有事务性</strong>。就算把关键代码搬到 RAM 里执行、成功擦完全部页，编程阶段掉电仍然会留下一个&quot;半新半旧&quot;的 app 区。这个半成品既跑不起来，也没有任何机制知道它坏了——直到复位后跳转时才 HardFault。</li></ol><p>第 3 点是最致命的。它意味着<strong>安装动作必须由一个不打算被覆盖的程序来执行</strong>，也就是 bootloader。</p><h3 id="_3-三个角色与两条分工线" tabindex="-1">3. 三个角色与两条分工线 <a class="header-anchor" href="#_3-三个角色与两条分工线" aria-label="Permalink to &quot;3. 三个角色与两条分工线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>执行者</th><th>动作</th><th>对象</th></tr></thead><tbody><tr><td>1</td><td>app（下载方）</td><td>写</td><td>外部 SPI Flash（交接区）</td></tr><tr><td>2</td><td>bootloader（安装方）</td><td>读</td><td>外部 SPI Flash（交接区）</td></tr><tr><td>3</td><td>bootloader（安装方）</td><td>写</td><td>内部 Flash</td></tr></tbody></table><p>两条不能越过的分工线：</p><ul><li><strong>app 永远不写内部 Flash</strong>，只写外部 Flash 的镜像槽与记录；</li><li><strong>bootloader 永远不下载</strong>，只读外部 Flash、校验、写内部 Flash。</li></ul><p>中间之所以需要一个&quot;交接区&quot;，是因为 app 与 bootloader 在时间上不共存：app 下载完就复位了，bootloader 上电时 app 的内存、栈、缓冲区全部蒸发。<strong>唯一能跨越复位传递的东西，只有掉电不丢的外部 Flash</strong>。</p><h2 id="二、-存储布局-两套-flash-各司其职" tabindex="-1">二、 存储布局：两套 Flash 各司其职 <a class="header-anchor" href="#二、-存储布局-两套-flash-各司其职" aria-label="Permalink to &quot;二、 存储布局：两套 Flash 各司其职&quot;">​</a></h2><p><img src="'+s+'" alt="两套存储与 A/B 槽位"></p><h3 id="_1-内部-flash-三段" tabindex="-1">1. 内部 Flash 三段 <a class="header-anchor" href="#_1-内部-flash-三段" aria-label="Permalink to &quot;1. 内部 Flash 三段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>地址</th><th>大小</th><th>说明</th></tr></thead><tbody><tr><td>bootloader</td><td><code>0x08000000</code></td><td>128KB</td><td>上电先跑，永不自我更新</td></tr><tr><td>flash app</td><td><code>0x08020000</code></td><td>128KB</td><td>唯一运行区，只由 bootloader 改写</td></tr><tr><td>SRAM app 暂存</td><td><code>0x08040000</code></td><td>128KB</td><td>给&quot;跳到 RAM 里跑的小程序&quot;预留，与在线升级无关</td></tr></tbody></table><p>内部 Flash 的 app 区只有 128KB：512KB 总量里 bootloader 与 SRAM app 暂存区各占 128KB，扣掉这两块还剩 256KB；当前 flash app 再占 128KB 后，剩余 128KB 刚好够再放一份同尺寸的 app 变体，一点余量都不剩。想在片上做&quot;新旧两份、各自可直接运行&quot;，就得把整片 Flash 用满。本工程因此把第二份镜像放到外部 Flash，完整取舍见第三节。</p><h3 id="_2-外部-spi-flash-分区" tabindex="-1">2. 外部 SPI Flash 分区 <a class="header-anchor" href="#_2-外部-spi-flash-分区" aria-label="Permalink to &quot;2. 外部 SPI Flash 分区&quot;">​</a></h3><p>板上挂了一颗 W25Q128，16MB，4096 个 4KB 扇区：</p><table tabindex="0"><thead><tr><th>扇区</th><th>地址</th><th>用途</th><th>写入者</th></tr></thead><tbody><tr><td>0 / 1</td><td><code>0x000000</code> / <code>0x001000</code></td><td>设备参数，双槽乒乓</td><td>app / bootloader</td></tr><tr><td>2 / 3</td><td><code>0x002000</code> / <code>0x003000</code></td><td><strong>升级控制记录</strong>，双槽乒乓</td><td>app 写、bootloader 改写</td></tr><tr><td>4 ~ 67</td><td><code>0x004000</code></td><td><strong>镜像槽 A</strong>，256KB</td><td>app</td></tr><tr><td>68 ~ 131</td><td><code>0x044000</code></td><td><strong>镜像槽 B</strong>，256KB</td><td>app</td></tr><tr><td>132 / 133</td><td><code>0x084000</code> / <code>0x085000</code></td><td>验签公钥记录，双槽乒乓（见 LV085）</td><td>PC 工具经 <code>spiflash</code> 写入</td></tr><tr><td>134 ~ 4094</td><td>—</td><td>预留</td><td>—</td></tr><tr><td>4095</td><td><code>0x3FF000</code></td><td>自检区，<code>spiflash test</code> 会擦</td><td>—</td></tr></tbody></table><p>两个槽各 256KB，是 app 区上限（128KB）的两倍，留出了将来镜像变大的余量。</p><h3 id="_3-为什么镜像槽一定要两个" tabindex="-1">3. 为什么镜像槽一定要两个 <a class="header-anchor" href="#_3-为什么镜像槽一定要两个" aria-label="Permalink to &quot;3. 为什么镜像槽一定要两个&quot;">​</a></h3><p>单槽就够了——如果升级永远成功。但升级恰恰是<strong>最可能失败的操作</strong>，所以每写一次新镜像，都要保证旧镜像还在原处、并且还是完整的。</p><p>双槽的做法是：<strong>永远写&quot;非 active 槽&quot;</strong>。</p><ul><li>当前内部 Flash 里跑的是 A 槽的拷贝，那么新镜像只写 B 槽；</li><li>搬运成功后 A 槽内容原封不动，它就是天然的&quot;上一版备份&quot;；</li><li>下一次升级写 A 槽，B 槽变成备份。</li></ul><p>这样一来，任何一次升级最多牺牲一份槽，另一份始终可用。</p><blockquote><p>这里有个容易忽略的细节：槽里存的是 <strong><code>N + 92</code> 字节的整帧</strong>，不是裸 bin。多出来的 92 字节（头 20 + 签名 64 + 尾 8）是 bootloader 独立校验的依据——它不信任记录，只信任自己算出来的结果。</p></blockquote><h2 id="三、-为什么必须拷贝到固定地址" tabindex="-1">三、 为什么必须拷贝到固定地址 <a class="header-anchor" href="#三、-为什么必须拷贝到固定地址" aria-label="Permalink to &quot;三、 为什么必须拷贝到固定地址&quot;">​</a></h2><p>第一节解决了&quot;谁来装&quot;，还剩一个前置问题：<strong>新镜像以什么形态存在、装到哪个地址</strong>。本工程认真比较过两条路——一是把内部 Flash 分成两槽、再编一份链接地址不同的 flash app，让两个槽都能直接运行；二是现在这套&quot;单一运行区 + 外部双槽，由 bootloader 拷到固定地址&quot;。下面把取舍摊开。</p><h3 id="_1-前提-运行地址等于链接地址" tabindex="-1">1. 前提：运行地址等于链接地址 <a class="header-anchor" href="#_1-前提-运行地址等于链接地址" aria-label="Permalink to &quot;1. 前提：运行地址等于链接地址&quot;">​</a></h3><p>Cortex-M3 从 Flash 就地取指（XIP），镜像里的地址在链接阶段就定死了：向量表第 1 项是复位入口的<strong>绝对</strong>地址，常量池、函数指针、字面量跳转表也全是绝对地址。所以&quot;运行副本放在哪个区&quot;必须等于&quot;编译时链接到哪个地址&quot;，这不是保守，是位置相关代码的硬约束。</p><p>因此&quot;让新镜像在它落脚的槽里直接运行&quot;只有两条出路：</p><ul><li><strong>每个槽各编一份</strong>：链接地址分别等于槽地址，两份镜像各自只能在对应的槽里运行；</li><li><strong>硬件把两个槽映射到同一地址</strong>：镜像永远链接在 <code>0x08000000</code>，靠映射电路决定物理上是哪一片。</li></ul><p>第二条路叫 Bank Swap，F103ZET6 没有——512KB 是单 Bank，没有地址映射电路。原理与有/无 Bank Swap 的五项对照见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c3115442925860.html">LV025-MCU有BankSwap落地方案</a> 第一节，XIP 与地址绑定的完整讨论见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c205c45e07232d.html">LV004-升级方案维度与选型</a> 第三节。于是只剩第一条路，或者第三条路——<strong>放弃&quot;在哪个槽就在哪运行&quot;，规定所有镜像只在同一个固定地址运行</strong>，装的时候先拷过去。前者要多编一份镜像，后者要多一次拷贝，下面算的就是这两笔账。</p><h3 id="_2-双变体的代价" tabindex="-1">2. 双变体的代价 <a class="header-anchor" href="#_2-双变体的代价" aria-label="Permalink to &quot;2. 双变体的代价&quot;">​</a></h3><p>双变体的代价不只是&quot;多编一个 bin&quot;。把两条路上每个环节摊平：</p><table tabindex="0"><thead><tr><th>环节</th><th>单份镜像（本工程）</th><th>双变体</th></tr></thead><tbody><tr><td>构建</td><td>一次编译、一个 bin</td><td>两个链接地址、两个 bin，构建脚本按参数各出一份</td></tr><tr><td>打包签名</td><td>一份签名</td><td>两份哈希、两份签名</td></tr><tr><td>下发</td><td>不关心设备当前在哪个槽</td><td>设备先上报槽位，服务器挑对应变体；或包内带两份，体积翻倍</td></tr><tr><td>bootloader 跳转</td><td>永远跳 <code>0x08020000</code></td><td>按 <code>active_slot</code> 选基址、设 <code>SCB-&gt;VTOR</code>、按对应变体比对校验值</td></tr><tr><td>回滚</td><td>把另一槽的拷贝搬回去</td><td>引导另一个变体</td></tr></tbody></table><p>最后一行最容易被忽略：双变体的回滚是&quot;换一个运行地址&quot;，不是&quot;覆盖回去&quot;——A 槽的 bin 放到 B 槽跑不起来，&quot;搬回去&quot;这条路在双变体下根本不存在。反过来说，本工程的槽内容与链接地址无关，因此可以搬来搬去，回滚才有材料可用。</p><h3 id="_3-本工程的选择" tabindex="-1">3. 本工程的选择 <a class="header-anchor" href="#_3-本工程的选择" aria-label="Permalink to &quot;3. 本工程的选择&quot;">​</a></h3><p>三条理由，按权重排：</p><p>（1）<strong>空间上没有余量</strong>。384KB 已经划走（bootloader、flash app、SRAM app 暂存区各 128KB），剩下 128KB 刚好够一份。双变体在这块板上是&quot;用满且零余量&quot;的方案，日后任何一块区域要长大都得重排分区——能跑，但没有退路。</p><p>（2）<strong>外部 Flash 本来就要</strong>。WiFi 下载的整帧镜像落在外部 SRAM，槽、升级记录、公钥都需要一块掉电不丢的区域。把两个 256KB 槽放进 16MB 的 W25Q128，边际成本接近零。</p><p>（3）<strong>跳转侧少一个分支</strong>。单份镜像意味着 bootloader 只有一条跳转路径：永远跳 <code>0x08020000</code>、永远一套向量表、永远一个校验期望。<code>go flash</code> 里唯一的额外判断是&quot;有没有 pending&quot;（第六节），不存在&quot;当前是哪个槽、该跳哪里&quot;这类分支。少一个分支就少一处&quot;调试时到底走的哪条路&quot;的困惑。</p><p>代价是安装变成一次整段擦写：拷贝期间掉电，运行区是半成品。这正是第六节的校验顺序、第七节的回滚窗口要解决的问题——<strong>拷贝方案把复杂度从&quot;版本管理&quot;挪到了&quot;断点恢复&quot;</strong>，而后者只在 bootloader 里实现一次。</p><h3 id="_4-换成有-bank-swap-的芯片会怎样" tabindex="-1">4. 换成有 Bank Swap 的芯片会怎样 <a class="header-anchor" href="#_4-换成有-bank-swap-的芯片会怎样" aria-label="Permalink to &quot;4. 换成有 Bank Swap 的芯片会怎样&quot;">​</a></h3><p>有 Bank Swap 时，两个 Bank 的地址由硬件对调，镜像永远链接并运行在 <code>0x08000000</code>，只编一份，升级只需往另一个 Bank 写、复位前改一次选项字节。落到本工程：选槽、记账、确认这套逻辑可以照搬，写槽的驱动从 SPI Flash 换成内部 Flash；bootloader 的&quot;搬运动作&quot;则退化成一次映射切换，第六节那张决策图会少掉一整条分支。</p><p>换句话说，拷贝方案是在没有 Bank Swap 的芯片上，用软件把&quot;写非活动区&quot;补齐——补的方式是搬运，不是映射。</p><h2 id="四、-升级的完整时序" tabindex="-1">四、 升级的完整时序 <a class="header-anchor" href="#四、-升级的完整时序" aria-label="Permalink to &quot;四、 升级的完整时序&quot;">​</a></h2><p><img src="'+n+`" alt="升级的三个阶段"></p><h3 id="_1-阶段一-下载与落盘-app-主导" tabindex="-1">1. 阶段一：下载与落盘（app 主导） <a class="header-anchor" href="#_1-阶段一-下载与落盘-app-主导" aria-label="Permalink to &quot;1. 阶段一：下载与落盘（app 主导）&quot;">​</a></h3><p>app 里只有一条命令：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>upd update                          # 默认 host=192.168.10.103, file=app.img</span></span>
<span class="line"><span>upd update 192.168.10.103 app.img   # 显式指定</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>它内部按顺序做六件事，每一步失败都直接退出、<strong>不动升级记录</strong>：</p><ol><li>判断是否已连上热点。注意这里<strong>只判断不重连</strong>——模块内部已经保存了 AP 配置，上电会自动连接；主动发 <code>AT+CWJAP</code> 会用默认参数覆盖掉它，还会打断正在进行的自动连接。</li><li>发一次 <code>AT+PING</code> 探 TFTP 主机。链路不通就别开始下载，否则每块数据都要等 3 秒超时重传。</li><li>等通道静默 800ms，再发一次 <code>AT+CIPMUX=1</code> 预热（原因见第八节第 3 小节）。</li><li>TFTP 下载整帧到外部 SRAM（<code>0x68000000</code>，1MB）。内部 RAM 只有 64KB，放不下 128KB 镜像。</li><li>整帧校验：魔数、长度自洽、尾标、载荷 CRC32、目标地址、Ed25519 验签——验签失败的镜像<strong>不写槽、不置 pending</strong>。</li><li>写非 active 槽，<strong>成功之后</strong>才写记录：<code>pending=1</code>、<code>pending_slot</code>、<code>img_len</code>、<code>img_crc32</code>。</li></ol><p>第 6 步的顺序不能反。若先置 <code>pending=1</code> 再写镜像，中途掉电会让 bootloader 去搬一个只写了一半的槽——而它拿到的长度和 CRC 恰好也来自这份记录，于是要么校验不过（浪费一次机会），要么更糟：旧的槽内容碰巧匹配（几乎不可能，但设计上不该依赖&quot;碰巧&quot;）。</p><h3 id="_2-阶段二-重启与搬运-bootloader-主导" tabindex="-1">2. 阶段二：重启与搬运（bootloader 主导） <a class="header-anchor" href="#_2-阶段二-重启与搬运-bootloader-主导" aria-label="Permalink to &quot;2. 阶段二：重启与搬运（bootloader 主导）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reboot          # app 侧执行，回到 bootloader</span></span>
<span class="line"><span>go flash        # bootloader 侧执行，先安装再跳转</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>go flash</code> 不再是&quot;直接跳到 <code>0x08020000</code>&quot;。它多了一段前置检查：读记录，<code>pending == 1</code> 才动手，否则维持原行为直接跳。</p><p>搬运过程见第六节。成功后的收尾是四个字段一起改：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>active_slot  = pending_slot     # 生效槽翻到新槽</span></span>
<span class="line"><span>pending      = 0                # 待安装标志清掉</span></span>
<span class="line"><span>confirmed    = 0               # 新程序还没人担保</span></span>
<span class="line"><span>attempts     = 1（换槽时重置）  # 未确认期间搬运次数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_3-阶段三-运行与确认-app-主导" tabindex="-1">3. 阶段三：运行与确认（app 主导） <a class="header-anchor" href="#_3-阶段三-运行与确认-app-主导" aria-label="Permalink to &quot;3. 阶段三：运行与确认（app 主导）&quot;">​</a></h3><p>新程序启动时会发现 <code>confirmed == 0</code>，于是打印一行醒目提示：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UPD: active slot B @ 0x00044000, running at 0x08020000, NOT confirmed, run &#39;upd ok&#39; after check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>人工确认功能正常后执行 <code>upd ok</code>，把 <code>confirmed</code> 置 1，回滚窗口关闭。</p><h2 id="五、-两处关键的数据结构" tabindex="-1">五、 两处关键的数据结构 <a class="header-anchor" href="#五、-两处关键的数据结构" aria-label="Permalink to &quot;五、 两处关键的数据结构&quot;">​</a></h2><p><img src="`+p+'" alt="记录信封与镜像帧"></p><p>整个流程里只有两种数据结构，但它们的字段语义必须完全对得上——app 写、bootloader 读，任何一处理解偏差都会让校验永远不过。</p><h3 id="_1-64b-记录信封" tabindex="-1">1. 64B 记录信封 <a class="header-anchor" href="#_1-64b-记录信封" aria-label="Permalink to &quot;1. 64B 记录信封&quot;">​</a></h3><p>记录和&quot;设备参数&quot;共用同一套信封格式，区别只在魔数：</p><table tabindex="0"><thead><tr><th>偏移</th><th>长度</th><th>内容</th><th>说明</th></tr></thead><tbody><tr><td>0</td><td>4B</td><td>魔数 <code>UPDT</code></td><td>与参数区的 <code>PRAM</code> 区分</td></tr><tr><td>4</td><td>1B</td><td>格式版本</td><td>当前 1，将来改结构靠它拒绝旧记录</td></tr><tr><td>5</td><td>1B</td><td>保留</td><td>固定 <code>0xFF</code></td></tr><tr><td>6</td><td>2B</td><td>载荷长度</td><td>固定 48</td></tr><tr><td>8</td><td>4B</td><td>写入序号</td><td>双槽比较&quot;谁更新&quot;</td></tr><tr><td>12</td><td>4B</td><td>载荷 CRC32</td><td>zlib 参数</td></tr><tr><td>16</td><td>48B</td><td>载荷</td><td>见下一张表</td></tr></tbody></table><p><strong>为什么记录本身也要双槽</strong>：写一个扇区必须先擦后写，而擦除是&quot;整扇区归 <code>0xFF</code>&quot;的原子性较差的操作。如果只有一份记录，擦完还没写回时掉电，记录就彻底没了——设备会以为&quot;从没升级过&quot;，把一个正在等待确认的新程序当成出厂状态。</p><p>乒乓写的规则很简单：<strong>改序号小的那份，序号取另一份 +1</strong>。这样任何时刻至少有一份完整记录，读取时取&quot;序号大且校验通过&quot;的那份。</p><h3 id="_2-升级载荷-upd-data-t-48b" tabindex="-1">2. 升级载荷 <code>upd_data_t</code>（48B） <a class="header-anchor" href="#_2-升级载荷-upd-data-t-48b" aria-label="Permalink to &quot;2. 升级载荷 `upd_data_t`（48B）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>谁写</th><th>语义</th></tr></thead><tbody><tr><td><code>active_slot</code></td><td>u32</td><td>bootloader</td><td>内部 Flash 内容来自哪个槽：0=A，1=B</td></tr><tr><td><code>confirmed</code></td><td>u32</td><td>app</td><td>正在跑的这一版是否已被人工确认</td></tr><tr><td><code>pending</code></td><td>u32</td><td>app 置 1、bootloader 清 0</td><td>是否有待安装镜像</td></tr><tr><td><code>pending_slot</code></td><td>u32</td><td>app</td><td>待安装的槽号</td></tr><tr><td><code>attempts</code></td><td>u32</td><td>bootloader</td><td>未确认期间的搬运次数</td></tr><tr><td><code>img_len</code></td><td>u32</td><td>app</td><td>整帧长度（<code>N + 92</code>）</td></tr><tr><td><code>img_crc32</code></td><td>u32</td><td>app</td><td><strong>整帧</strong> CRC32</td></tr><tr><td><code>reserved[5]</code></td><td>5×u32</td><td>—</td><td>预留，将来放程序版本号</td></tr></tbody></table><p><code>active_slot</code> 的语义容易被误解：它不是&quot;从哪个槽运行&quot;——<strong>CPU 永远只在内部 Flash 上执行</strong>。它表达的是&quot;<code>0x08020000</code> 里这份内容对应哪个槽&quot;，也就是当前运行内容的来源；需要回滚到上一版时，应取另一个非 active 槽。</p><h3 id="_3-iapbin03-帧" tabindex="-1">3. IAPBIN03 帧 <a class="header-anchor" href="#_3-iapbin03-帧" aria-label="Permalink to &quot;3. IAPBIN03 帧&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>偏移</th><th>长度</th><th>内容</th></tr></thead><tbody><tr><td>魔数</td><td>0</td><td>8B</td><td><code>IAPBIN03</code></td></tr><tr><td>载荷长度</td><td>8</td><td>4B</td><td>N</td></tr><tr><td>载荷 CRC32</td><td>12</td><td>4B</td><td>只覆盖 N 字节载荷</td></tr><tr><td>目标地址</td><td>16</td><td>4B</td><td><code>0x08020000</code> 或 <code>0x20007000</code></td></tr><tr><td>载荷</td><td>20</td><td>N</td><td>裸 bin</td></tr><tr><td>Ed25519 签名</td><td>20+N</td><td>64B</td><td>覆盖头部 20B + 载荷 N B</td></tr><tr><td>尾标</td><td>20+N+64</td><td>8B</td><td><code>IAPEOF03</code></td></tr></tbody></table><p>与第二版相比只多了 64 字节签名，头部布局一字未动；旧版帧（无签名）一律拒绝，不存在降级开关。<strong>签名把头部也一起签了</strong>——长度、CRC32、目标地址任何一个被改，验签都会失败，&quot;换信封复用旧签名&quot;的攻击面被堵死。帧格式与验签原理的完整讨论见 <a href="./LV085-Ed25519签名校验原理.html">LV085-Ed25519签名校验原理</a>。</p><p>帧由 <code>tools/pack_iap.py -k keys/iap_priv.pem</code> 生成，打包时必须提供私钥（不存在无签名帧这个产物形态），带向量表检查（栈顶必须在 <code>0x2000xxxx</code>、复位向量必须在 <code>0x0802xxxx</code>），拿错产物（比如调试版链接在 <code>0x08000000</code>）会在打包阶段就被拒。</p><h3 id="_4-两层-crc-与一层签名的分工" tabindex="-1">4. 两层 CRC 与一层签名的分工 <a class="header-anchor" href="#_4-两层-crc-与一层签名的分工" aria-label="Permalink to &quot;4. 两层 CRC 与一层签名的分工&quot;">​</a></h3><p>链路上有三道校验，各有各的职责，别混：</p><ul><li><strong>帧内 <code>CRC32</code>（偏移 12）</strong>：覆盖 N 字节载荷，回答&quot;这份 bin 在传输过程中有没有坏&quot;；</li><li><strong>记录里的 <code>img_crc32</code></strong>：覆盖整帧 <code>N + 92</code>（含签名），回答&quot;槽里这一份和当初写进去的是不是同一份&quot;；</li><li><strong>Ed25519 验签</strong>：覆盖头部 + 载荷，回答&quot;这份 bin 是不是私钥持有者签发的&quot;——CRC 管得住意外、管不住故意，这是签名存在的原因。</li></ul><p>前两者在下载时校验一次、搬运前各重新算一次；验签则在下载、落槽、搬运前三处都要过。两个 CRC 的算法参数必须与 bootloader 的 <code>iap_crc32()</code> 完全一致：多项式 <code>0xEDB88320</code> 反射、初值与终值异或 <code>0xFFFFFFFF</code>（即 zlib 实现）。app 侧为了省查表空间是逐位算的，结果相同。CRC 的数学原理见 <a href="./LV080-CRC32校验原理.html">LV080-CRC32校验原理</a>。</p><h2 id="六、-go-flash-的搬运逻辑" tabindex="-1">六、 go flash 的搬运逻辑 <a class="header-anchor" href="#六、-go-flash-的搬运逻辑" aria-label="Permalink to &quot;六、 go flash 的搬运逻辑&quot;">​</a></h2><p><img src="'+l+`" alt="go flash 的搬运决策"></p><h3 id="_1-决策入口" tabindex="-1">1. 决策入口 <a class="header-anchor" href="#_1-决策入口" aria-label="Permalink to &quot;1. 决策入口&quot;">​</a></h3><p><code>go flash</code> 进来先看 <code>pending</code>。为 0 走原来的路径：校验 <code>0x08020000</code> 的向量表，合法就跳。为 1 才进入安装流程。</p><p>这里有个取舍值得说明：安装<strong>不自动做</strong>，必须由人敲 <code>go flash</code> 触发。自动安装（上电就检查 pending）看起来更方便，但会把&quot;设备无法启动&quot;这个故障和&quot;本来就想重启&quot;混在一起，调试时很难判断到底发生了什么。手动触发让每一步都可观测。</p><h3 id="_2-七项校验的顺序不能换" tabindex="-1">2. 七项校验的顺序不能换 <a class="header-anchor" href="#_2-七项校验的顺序不能换" aria-label="Permalink to &quot;2. 七项校验的顺序不能换&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IAPBIN03 魔数 → 载荷长度自洽 → 目标地址 → IAPEOF03 尾标 → 载荷 CRC32 → 整帧 CRC32 → Ed25519 验签</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>顺序是有讲究的：</p><ul><li><strong>魔数</strong>放第一位，能立刻挡掉&quot;空槽&quot;（全 <code>0xFF</code>）和&quot;垃圾数据&quot;；</li><li><strong>长度自洽</strong>必须在取签名与尾标之前。签名偏移是 <code>20 + payload_len</code>，如果先按一个未经校验的 <code>payload_len</code> 去取，很可能直接越界读出 SRAM 之外的地址；</li><li><strong>目标地址</strong>放在 CRC 之前，是因为它是&quot;要不要装&quot;的判断依据——SRAM 版镜像（目标 <code>0x20007000</code>）根本不该进 A/B 槽；</li><li><strong>两个 CRC</strong> 放倒数第二、三位，计算最贵，前面的廉价判断先把九成错误挡掉；</li><li><strong>验签</strong>殿后，是全部校验里最贵的一步（72MHz 上约 50~60ms），只花在结构完好的帧上。它同时是唯一能挡住&quot;<em>crc 正确但内容被调包</em>&quot;的关口——签名覆盖头部与载荷，前面任何一项被绕过（比如攻击者同步重算了 CRC），到这里仍然现形。</li></ul><p>任何一项不过，都打印具体原因并<strong>保留记录</strong>，然后照旧跳当前镜像。</p><h3 id="_3-先写-flash-再记账" tabindex="-1">3. 先写 Flash 再记账 <a class="header-anchor" href="#_3-先写-flash-再记账" aria-label="Permalink to &quot;3. 先写 Flash 再记账&quot;">​</a></h3><p>搬运成功的收尾顺序是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写 0x08020000（擦页 → 编程 → 回读 CRC32 比对）</span></span>
<span class="line"><span>    ↓ 成功</span></span>
<span class="line"><span>写记录（active / pending / confirmed / attempts）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>反过来的话，一旦在&quot;记账完成、Flash 未写完&quot;之间掉电，记录会声称 <code>active</code> 已经是新槽，而内部 Flash 里还是旧镜像——下次回滚就会搬错东西。按现在的顺序，最坏情况是&quot;装好了但没记账&quot;，此时记录仍是 <code>pending=1</code>，下次 <code>go flash</code> 会重装一遍。<strong>安装动作是幂等的，记账不是</strong>，所以幂等的那个先做。</p><h3 id="_4-失败为什么不会变砖" tabindex="-1">4. 失败为什么不会变砖 <a class="header-anchor" href="#_4-失败为什么不会变砖" aria-label="Permalink to &quot;4. 失败为什么不会变砖&quot;">​</a></h3><p>三条防线叠在一起：</p><ol><li><strong>擦除发生在校验之后</strong>。七项校验全过才碰内部 Flash，任何&quot;镜像本身有问题&quot;的情况（含验签失败）都不会破坏现有程序。</li><li><strong>写入前不擦除已确认的槽</strong>。搬运只动 <code>0x08020000</code>，A/B 槽保持原样，随时可再装一次。</li><li><strong>失败继续跳旧程序</strong>。搬运失败不是&quot;停在 bootloader 等死&quot;，而是照旧跳 <code>0x08020000</code>——那里还是完整的旧程序。</li></ol><p>真正无法恢复的只有一种情况：写内部 Flash 的过程中掉电。此时 <code>0x08020000</code> 是半成品，但记录里 <code>pending</code> 还在，重新上电后 <code>go flash</code> 会重新搬一遍，把半成品覆盖掉。只要槽里的镜像还在，这个循环总能收敛。</p><h2 id="七、-状态机与回滚窗口" tabindex="-1">七、 状态机与回滚窗口 <a class="header-anchor" href="#七、-状态机与回滚窗口" aria-label="Permalink to &quot;七、 状态机与回滚窗口&quot;">​</a></h2><p><img src="`+r+`" alt="升级记录的状态流转"></p><h3 id="_1-三个状态" tabindex="-1">1. 三个状态 <a class="header-anchor" href="#_1-三个状态" aria-label="Permalink to &quot;1. 三个状态&quot;">​</a></h3><p>记录只有三种稳定形态：</p><table tabindex="0"><thead><tr><th>状态</th><th><code>pending</code></th><th><code>confirmed</code></th><th>含义</th></tr></thead><tbody><tr><td>稳定态</td><td>0</td><td>1</td><td>内部 Flash 与 active 槽一致，且已被确认</td></tr><tr><td>下载完成</td><td>1</td><td>不变</td><td>非 active 槽有一份新镜像等安装</td></tr><tr><td>待确认</td><td>0</td><td>0</td><td>新镜像已装上，但还没人担保</td></tr></tbody></table><p>状态之间的三条转移，正好对应三个动作：<code>upd update</code>（稳定 → 下载完成）、<code>go flash</code>（下载完成 → 待确认）、<code>upd ok</code>（待确认 → 稳定）。</p><h3 id="_2-回滚窗口到底锁住了什么" tabindex="-1">2. 回滚窗口到底锁住了什么 <a class="header-anchor" href="#_2-回滚窗口到底锁住了什么" aria-label="Permalink to &quot;2. 回滚窗口到底锁住了什么&quot;">​</a></h3><p><code>confirmed = 0</code> 的那段时间，就是回滚窗口。它锁住的不是代码，而是<strong>语义</strong>：</p><ul><li>内部 Flash 里是新程序，<code>active_slot</code> 指向新槽；</li><li>另一槽里躺着上一版，内容完整；</li><li>记录明确写着&quot;这一版没人确认过&quot;。</li></ul><p>如果将来加自动回滚，判据就是它：<strong>连续启动失败 / <code>attempts</code> 超阈值 → 把另一槽搬回来</strong>。现在的实现只写记录、不做判断，也就是说窗口是&quot;敞开的但没有自动关门的人&quot;。</p><h3 id="_3-目前没做的三件事" tabindex="-1">3. 目前没做的三件事 <a class="header-anchor" href="#_3-目前没做的三件事" aria-label="Permalink to &quot;3. 目前没做的三件事&quot;">​</a></h3><p>如实记录边界，避免后来者误以为已经具备：</p><ol><li><strong>没有自动回滚</strong>。<code>go rollback</code> 尚未实现，回退只能靠重新下载上一版。</li><li><strong>没有&quot;未确认禁止再升级&quot;</strong>。<code>confirmed = 0</code> 时再次 <code>upd update</code>，会直接覆盖非 active 槽——那份备份就丢了。最初的设想是拒绝本次升级以保护备份，实测里为了调试方便先放开了。</li><li><strong>没有程序版本字段</strong>。<code>reserved[5]</code> 空着。帧格式已升级到 <code>IAPBIN03</code>（签名版），版本号字段仍留待将来需要显示&quot;当前 v1.2，可回滚到 v1.1&quot;时再启用。</li></ol><p>另外还有一处不一致要留意：bootloader 的 <code>update</code>（网口 TFTP）、串口 IAP、TCP IAP 三条直装通道<strong>都直接写 <code>0x08020000</code>，不写升级记录</strong>。它们装完之后，&quot;内部 Flash 内容 == active 槽内容&quot;这个不变量就暂时失效了。做自动回滚之前，必须先把这几条通道也纳入记账。</p><h2 id="八、-实现要点与实测" tabindex="-1">八、 实现要点与实测 <a class="header-anchor" href="#八、-实现要点与实测" aria-label="Permalink to &quot;八、 实现要点与实测&quot;">​</a></h2><h3 id="_1-命令分布" tabindex="-1">1. 命令分布 <a class="header-anchor" href="#_1-命令分布" aria-label="Permalink to &quot;1. 命令分布&quot;">​</a></h3><p>两侧命令不同，别混用：</p><table tabindex="0"><thead><tr><th>侧</th><th>命令</th><th>作用</th></tr></thead><tbody><tr><td>app</td><td><code>upd update [host] [file]</code></td><td>一键下载 + 落槽 + 置 pending</td></tr><tr><td>app</td><td><code>upd status</code></td><td>打印记录、槽地址、运行地址</td></tr><tr><td>app</td><td><code>upd ok</code></td><td>确认当前程序，关闭回滚窗口</td></tr><tr><td>bootloader</td><td><code>upd get</code></td><td>打印记录</td></tr><tr><td>bootloader</td><td><code>upd set key=value ...</code></td><td>手工造记录（调试用）</td></tr></tbody></table><p>默认主机与文件名集中在 <code>flash-app/Drivers/BSP/Update/upd.h</code> 的 <code>UPD_OTA_HOST_DEFAULT</code> 与 <code>UPD_OTA_FILE_DEFAULT</code>。</p><h3 id="_2-一次实测日志" tabindex="-1">2. 一次实测日志 <a class="header-anchor" href="#_2-一次实测日志" aria-label="Permalink to &quot;2. 一次实测日志&quot;">​</a></h3><p><code>upd update</code>（active 在 A，写 B 槽）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UPD: wifi up, ping 192.168.10.103 9 ms, fetching app.img ...</span></span>
<span class="line"><span>[ESP8266] recv 8192 bytes</span></span>
<span class="line"><span>[ESP8266] recv 16384 bytes</span></span>
<span class="line"><span>[ESP8266] recv 24576 bytes</span></span>
<span class="line"><span>[ESP8266] recv 32768 bytes</span></span>
<span class="line"><span>[ESP8266] recv 40960 bytes</span></span>
<span class="line"><span>[ESP8266] recv 49152 bytes</span></span>
<span class="line"><span>UPD: 56776 bytes ok (payload 56684), staging to slot B @ 0x00044000 ...</span></span>
<span class="line"><span>UPD: slot B ready (56776 bytes, crc32 0x5BBADA10), run &#39;go flash&#39; in bootloader</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><code>go flash</code>（搬运）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UPD: pending slot B @ 0x00044000, 56776 bytes, installing...</span></span>
<span class="line"><span>IAP: flashing 56684 bytes to 0x08020000 (28 page(s)), please wait...</span></span>
<span class="line"><span>IAP: flash write OK, readback CRC32 verified</span></span>
<span class="line"><span>UPD: slot B installed, active slot is B, attempts 1; run &#39;upd ok&#39; in the app once it works</span></span>
<span class="line"><span>IAP: jump to APP at 0x08020000 (MSP 0x20003738, reset 0x08020299)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>upd status</code>（搬运后）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UPD: active_slot  = B (1) @ 0x00044000, running at 0x08020000</span></span>
<span class="line"><span>UPD: confirmed    = 0 (NOT confirmed, run &#39;upd ok&#39; once it works)</span></span>
<span class="line"><span>UPD: pending      = 0 (nothing to install)</span></span>
<span class="line"><span>UPD: pending_slot = B (1) @ 0x00044000</span></span>
<span class="line"><span>UPD: attempts     = 1</span></span>
<span class="line"><span>UPD: img_len      = 56776</span></span>
<span class="line"><span>UPD: img_crc32    = 0x5BBADA10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>56KB 镜像（<code>56684 + 92</code> 字节帧）经 ESP8266 的 AT 透传下载约 35 秒（TFTP 512B 一块，111 块），写槽约 2 秒，搬运安装约 8 秒。全程阻塞主循环，属于&quot;接受这个时间&quot;的取舍。</p><p>签名校验拒绝的实测同样值得记录——把载荷改一个字节并同步重算 CRC32 后再走一遍 <code>upd update</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UPD: wifi up, ping 192.168.10.103 174 ms, fetching bad_sig.img ...</span></span>
<span class="line"><span>[ESP8266] signature invalid (target 0x08020000, 56684 bytes), image rejected</span></span>
<span class="line"><span>UPD: image verify failed: image signature invalid</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>CRC 是重算过的，所以 CRC 关照常通过；拦下它的是最后一关 Ed25519 验签。此后核对 <code>upd status</code> 与非 active 槽内容，与失败前逐字节一致——验签失败不留下任何副作用。</p><h3 id="_3-踩过的坑-ping-之后不能立刻建链" tabindex="-1">3. 踩过的坑：ping 之后不能立刻建链 <a class="header-anchor" href="#_3-踩过的坑-ping-之后不能立刻建链" aria-label="Permalink to &quot;3. 踩过的坑：ping 之后不能立刻建链&quot;">​</a></h3><p>这是本次改动里最隐蔽的一个问题，值得单独记一笔。</p><p>给升级流程加上&quot;先 ping 再下载&quot;之后，<code>upd update</code> 每次都回：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UPD: wifi up, ping 192.168.10.103 52 ms, fetching app.img ...</span></span>
<span class="line"><span>UPD: download failed: connect failed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>失败发生在建链阶段，耗时很短。奇怪的是用 <code>at</code> 命令逐条手工发同样的指令却全部成功：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>at AT+PING=&quot;192.168.10.103&quot;     → +4 / OK</span></span>
<span class="line"><span>at AT+CIPMUX=1                  → OK</span></span>
<span class="line"><span>at AT+CIPSTART=0,&quot;UDP&quot;,...      → 0,CONNECT / OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>差别在于<strong>时间</strong>。<code>atk_mw8266d_ping_host()</code> 是&quot;收到结论就返回&quot;的实现，模块回完 <code>+4</code> 之后还要吐末尾的 <code>OK</code>；代码紧接着就发 <code>AT+CIPMUX=1</code>，模块此时仍在处理上一条事务，新指令被静默丢弃或应答错位，<code>net_wait_for(&quot;OK&quot;)</code> 匹配到的是迟到的旧 <code>OK</code>，于是 CIPSTART 提前发出、判定失败。手工执行时工具调用之间天然隔了几秒，正好避开这个窗口——这也是为什么&quot;手工能通、代码不通&quot;。</p><p>最终叠了三层防护：</p><ol><li>ping 之后等通道<strong>连续 800ms 无帧</strong>，再清空接收缓冲；</li><li>建链前单独发一次 <code>AT+CIPMUX=1</code> 把 TCP/IP 事务预热（<code>tftp_get</code> 内部还会再发一次，幂等）；</li><li>建链仍失败时，发 <code>AT+CIPCLOSE=0</code> 清掉残留 link，等 500ms 重试一次。</li></ol><h3 id="_4-自测清单" tabindex="-1">4. 自测清单 <a class="header-anchor" href="#_4-自测清单" aria-label="Permalink to &quot;4. 自测清单&quot;">​</a></h3><p>按这个顺序走一遍，能覆盖所有关键分支：</p><ul><li>[ ] <code>upd update</code> 后 <code>upd status</code> 里 <code>pending=1</code>，且 <code>pending_slot</code> 与当前 <code>active_slot</code> <strong>相反</strong></li><li>[ ] <code>reboot</code> 后 <code>upd get</code> 仍能读到 <code>pending=1</code>（记录掉电不丢）</li><li>[ ] <code>go flash</code> 打印 4 行安装日志，跳到新镜像</li><li>[ ] 启动打印 <code>NOT confirmed</code>，<code>upd ok</code> 后变 <code>confirmed</code></li><li>[ ] 再 <code>reboot</code> + <code>go flash</code>：没有 <code>installing</code> 日志，直接跳转</li><li>[ ] 再执行一次 <code>upd update</code>：这次应写入<strong>另一个</strong>槽（乒乓切换）</li><li>[ ] 发一条篡改帧（改载荷并重算 CRC）：报 <code>signature invalid</code>，槽与记录原样不动</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,152)])])}const _=a(i,[["render",c]]);export{x as __pageData,_ as default};
